class Solution {
public:
    bool canReach(string s, int minJump, int maxJump) {
        if (s.back() != '0') return false;

        int n = s.size();
        vector<bool> dp(n, false);
        dp[0] = true;
        int reachCount = 0;

        for (int i = 1; i < n; ++i) {
            if (i >= minJump && dp[i - minJump]) reachCount++;
            if (i > maxJump && dp[i - maxJump - 1]) reachCount--;

            if (reachCount > 0 && s[i] == '0') {
                dp[i] = true;
            }
        }
        return dp[n - 1];
    }
};

class Solution {
    public boolean canReach(String s, int minJump, int maxJump) {
        if (s.charAt(s.length() - 1) != '0') return false;

        int n = s.length();
        boolean[] dp = new boolean[n];
        dp[0] = true;
        int reachCount = 0;

        for (int i = 1; i < n; ++i) {
            if (i >= minJump && dp[i - minJump]) reachCount++;
            if (i > maxJump && dp[i - maxJump - 1]) reachCount--;

            if (reachCount > 0 && s.charAt(i) == '0') {
                dp[i] = true;
            }
        }
        return dp[n - 1];
    }
}

/**
 * @param {string} s
 * @param {number} minJump
 * @param {number} maxJump
 * @return {boolean}
 */
var canReach = function(s, minJump, maxJump) {
    if (s[s.length - 1] !== '0') return false;

    const n = s.length;
    const dp = Array(n).fill(false);
    dp[0] = true;
    let reachCount = 0;

    for (let i = 1; i < n; ++i) {
        if (i >= minJump && dp[i - minJump]) reachCount++;
        if (i > maxJump && dp[i - maxJump - 1]) reachCount--;

        if (reachCount > 0 && s[i] === '0') {
            dp[i] = true;
        }
    }
    return dp[n - 1];
};
